events.text:
return {
    read(id) { return records.get(id) ?? ""; },
    write(id, text) {
      records.set(id, text);
      const event = { id, text, revision: ++revision };
      for (const listener of [...listeners]) {
        if (listeners.has(listener)) listener(event);
      }
      return event;
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };

return {
    open(id, visit) {
      const request = ++navigation;
      retire();
      if (request !== navigation) return;
      const task = createTrailingTask(text => store.write(id, text), 120, timers);
      current = { id, visit, task, stop: attachSaveStatus(store, id, renderStatus) };
      renderDocument({ id, visit, text: store.read(id) });
    },
    selection: () => current && { id: current.id, visit: current.visit },
    edit(text) {
      if (current) current.task.push(text);
    },
    close() {
      ++navigation;
      retire();
    },
  };

return {
    commit(visit) { selected = { ...visit }; trail.push({ ...visit }); publish(); },
    clear() { selected = null; publish(); },
  };

return {
    query(text) { task.push(text); },
    // A hidden preview has no use for a pending query; reopen starts fresh.
    hide() { task.cancel(); },
  };

browserTimers = {
  schedule(callback, delay) { return setTimeout(callback, delay); },
  cancel(handle) { clearTimeout(handle); },
}

return {
    push(...args) {
      if (handle !== null) timers.cancel(handle);
      pending = args;
      handle = timers.schedule(flush, delay);
    },
    flush,
    cancel() {
      if (handle !== null) timers.cancel(handle);
      handle = null;
      pending = null;
    },
  };

navigation = {
    select(id) {
      const visit = ++nextVisit;
      editor.open(id, visit);
      projection.commit({ id, visit });
    },
    edit(text) { editor.edit(text); },
    close() { editor.close(); projection.clear(); },
  }
